python3 -c "import re;
def highlight_title(title: str, query: str) -> str:
    pieces = query.split()
    terms = set()
    for p in pieces:
        term = re.sub(r'^[^a-zA-Z0-9]+', '', p)
        term = re.sub(r'[^a-zA-Z0-9]+$', '', term)
        if term:
            terms.add(term)
    if not terms:
        return title
    sorted_terms = sorted(list(terms), key=len, reverse=True)
    pattern = r'(?<![a-zA-Z0-9])(' + '|'.join(re.escape(t) for t in sorted_terms) + r')(?![a-zA-Z0-9])'
    return re.sub(pattern, r'<b>\1</b>', title, flags=re.IGNORECASE)

print(highlight_title('Quokka cluster provisioning checklist', '\"quokka\"'))
print(highlight_title('Wombat telemetry pipeline', 'wombat pipeline'))
